func (o *redhatBase) parseOwnerPkgs(stdout string) (pkgNames []string, err error) {
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		if strings.HasSuffix(line, "Permission denied") ||
			strings.HasSuffix(line, "is not owned by any package") ||
			strings.HasSuffix(line, "No such file or directory") {
			continue
		}
		pack, err := o.parseInstalledPackagesLine(line)
		if err != nil {
			return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s: %w", line, err)
		}
		pkgNames = append(pkgNames, pack.Name)
	}
	if err := scanner.Err(); err != nil {
		return nil, xerrors.Errorf("Failed to read rpm -qf output: %w", err)
	}
	return pkgNames, nil
}

func (o *redhatBase) rpmQa() string {
	const old = `rpm -qa --queryformat "%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{ARCH}\n"`
	const new = `rpm -qa --queryformat "%{NAME} %{EPOCHNUM} %{VERSION} %{RELEASE} %{ARCH}\n"`
	switch o.Distro.Family {
	case config.SUSEEnterpriseServer:
		if v, _ := o.Distro.MajorVersion(); v < 12 {
			return old
		}
		return new
	default:
		if v, _ := o.Distro.MajorVersion(); v < 6 {
			return old
		}
		return new
	}
}

